  function selectedRacers(root){return qa('.race-v2-racers input:checked',root).map(function(c){return profiles()[Number(c.value)]}).filter(Boolean)}
  function ordinal(value){var mod100=value%100;if(mod100>=11&&mod100<=13)return value+'th';return value+(value%10===1?'st':value%10===2?'nd':value%10===3?'rd':'th')}
