  function cleanDuplicateRider(rider){return{name:rider.name,number:rider.number,tag:rider.tag||''}}
  function freshDuplicateSchedule(source){var racers=[];(source.schedule||[]).forEach(function(stage){(stage.racers||[]).forEach(function(rider){if(!racers.some(function(saved){return riderKey(saved)===riderKey(rider)}))racers.push(cleanDuplicateRider(rider))})});racers=shuffle(racers);var c=source.configuration||{},elimination=source.type==='Double Elimination'||source.type==='Single Elimination'||source.type==='Bracket racing';if(elimination){var heatCount=Math.max(1,Math.min(Number(c['v2-heat-count'])||1,Math.max(1,racers.length))),groups=Array.from({length:heatCount},function(){return[]});racers.forEach(function(rider,index){groups[index%heatCount].push(rider)});var schedule=groups.map(function(group,index){return{name:'Heat '+(index+1),kind:'HEAT',racers:group}});if(source.type!=='Single Elimination'){var lcqCount=Math.max(1,Number(c['v2-lcq-count'])||1);for(var i=0;i<lcqCount;i++)schedule.push({name:'LCQ '+(i+1),kind:'LCQ',racers:[]})}schedule.push({name:'Main Event',kind:'MAIN',racers:[]});return schedule}if(source.type==='Time attack')return racers.map(function(rider){return{name:'Time Attack "'+rider.name+'"',kind:'TIME_ATTACK',racers:[rider]}});return(source.schedule||[]).map(function(stage){var clean={name:stage.name,kind:stage.kind,racers:shuffle(racers)};if(stage.teams)clean.teams=stage.teams.map(function(team){return shuffle(team.map(cleanDuplicateRider))});return clean})}
