(function(){
  function wireScanGate(){
    var timer=document.querySelector('#v2-live-timer');
    if(!timer||document.querySelector('#v2-scan-gate'))return;
    var panel=timer.parentElement,wrap=document.createElement('div');
    wrap.id='v2-scan-gate';wrap.className='race-v2-scan-hidden';
    wrap.innerHTML='<input id="v2-scan-input" aria-label="RFID scanner" disabled><p id="v2-scan-message" aria-live="polite"></p>';
    panel.append(wrap);
    var input=document.querySelector('#v2-scan-input'),message=document.querySelector('#v2-scan-message');
    document.querySelectorAll('.race-v2-control').forEach(function(button){
      button.addEventListener('click',function(){
        var green=button.dataset.state==='GREEN',host=document.querySelector('#race-v2-host'),timeAttack=host&&host.dataset.raceType==='Time attack';
        input.disabled=!green;
        input.placeholder=green?(timeAttack?'Scan RFID to start, then scan again to finish':'Scan current heat racer RFID tag'):'Scanning disabled until Green';
        message.textContent=green?(timeAttack?'Green armed. First RFID scan starts the timer.':'Scanning enabled for racers in the current race.'):'Scanning stopped.';
        if(!green){input.value='';input.blur()}
      });
    });
    input.addEventListener('keydown',function(event){
      if(event.key!=='Enter'||input.disabled||!input.value.trim())return;
      var host=document.querySelector('#race-v2-host');if(host&&host.dataset.raceType==='Time attack'){if(host.dataset.timeAttackRunning==='true')window.raceV2FinishTimeAttack(false);else window.raceV2StartTimeAttack();input.value='';return}
      var results=document.querySelector('#v2-live-results');
      if(results&&results.querySelector('.race-v2-empty'))results.innerHTML='';
      if(results){var row=document.createElement('div'),display=window.raceV2ResolveTeamTag&&host?window.raceV2ResolveTeamTag(host.dataset.raceId,input.value.trim()):input.value.trim();row.className='race-v2-result';row.innerHTML='<span>—</span><strong>'+display+'</strong><span>'+timer.textContent+'</span>';results.append(row)}
      input.value='';
    });
  }
  setInterval(wireScanGate,300);
})();

(function(){
  var SESSION_KEY='complex-control-local-session';
  var PROFILE_KEY='complex-control-racer-profiles';
  function session(){try{return JSON.parse(localStorage.getItem(SESSION_KEY)||'null')}catch(e){return null}}
  function isProfileAdmin(){var current=session(),role=current&&(current.role||current.profile||current.type);return String(role||'').trim().toLowerCase()==='admin'}
  function savedProfiles(){try{return JSON.parse(localStorage.getItem(PROFILE_KEY)||'[]')}catch(e){return[]}}
  function syncProfileList(){
    var list=document.querySelector('#profile-list');if(!list)return;var riders=savedProfiles(),signature=JSON.stringify(riders);if(list.dataset.racerSignature===signature)return;list.dataset.racerSignature=signature;list.innerHTML='';
    if(!riders.length){list.textContent='No racer profiles added yet.';return}
    riders.forEach(function(racer,index){var row=document.createElement('p'),name=document.createElement('strong'),details=document.createTextNode(' · #'+(racer.number||'—')+' · '+(racer.tag||'No tag')+' '),remove=document.createElement('button');name.textContent=racer.name||'Unnamed racer';remove.type='button';remove.textContent='Delete';remove.dataset.confirmDelete=index;row.append(name,details,remove);list.append(row)});
  }
  function applyProfilePermissions(){
    syncProfileList();var list=document.querySelector('#profile-list');if(!list)return;var isAdmin=isProfileAdmin(),form=document.querySelector('.local-profile-form');
    if(form){form.querySelectorAll('input,select,button').forEach(function(control){control.disabled=!isAdmin});form.classList.toggle('race-v2-view-only',!isAdmin)}
    list.querySelectorAll('p').forEach(function(row){var deleteButton=row.querySelector('[data-delete-profile],[data-confirm-delete]'),calibrate=row.querySelector('.race-v2-calibrate');if(isAdmin&&!calibrate&&deleteButton){calibrate=document.createElement('button');calibrate.type='button';calibrate.className='race-v2-calibrate';calibrate.textContent='Hold to Calibrate';row.insertBefore(calibrate,deleteButton);wireCalibration(calibrate)}if(calibrate)calibrate.hidden=!isAdmin;if(deleteButton)deleteButton.hidden=!isAdmin});
  }
  function wireCalibration(button){
    var frame=0,started=0;
    function reset(){if(frame)cancelAnimationFrame(frame);frame=0;started=0;button.style.setProperty('--calibration-progress','0%')}
    function progress(now){if(!started)started=now;var percent=Math.min(100,(now-started)/20);button.style.setProperty('--calibration-progress',percent+'%');if(percent>=100){frame=0;button.textContent='Calibration Test Complete';button.classList.add('complete');window.setTimeout(function(){button.textContent='Hold to Calibrate';button.classList.remove('complete');reset()},1400);return}frame=requestAnimationFrame(progress)}
    button.addEventListener('pointerdown',function(e){e.preventDefault();reset();frame=requestAnimationFrame(progress)});['pointerup','pointerleave','pointercancel'].forEach(function(name){button.addEventListener(name,reset)});
  }
  document.addEventListener('click',function(e){var nav=e.target.closest('.topbar nav button');if(nav&&nav.textContent.trim()==='Racer Profiles')window.setTimeout(applyProfilePermissions,0)},true);
  var observer=new MutationObserver(function(records){if(records.some(function(record){return record.target.id==='profile-list'||(record.target.closest&&record.target.closest('#profile-list'))}))window.setTimeout(applyProfilePermissions,0)});observer.observe(document.documentElement,{childList:true,subtree:true});
  window.setInterval(applyProfilePermissions,1000);applyProfilePermissions();
})();
